  220	 * first claim wins, and a double submit or retry finishes that same Organization.
  221	 */
  222	export const createOrganization = Effect.fnUntraced(function* (
  223	  checked: CheckedSession,
  224	  name: string,
  225	  allowlist: OrganizationCreationAllowlist,
  226	) {
  227	  const index = yield* PeopleIndex;
  228	  const ids = yield* NewIds;
  229	  const { session } = checked;
  230	
  231	  const existing = yield* index.claimOf(session.identity.userId);
  232	  if (Option.isSome(existing)) return yield* finishCreation(session, existing.value);
  233	
  234	  if (Option.isSome(checked.member)) return yield* new Forbidden();
  235	  const decision = decideSignIn(session.identity, yield* candidatesOf(session), allowlist);
  236	  if (decision._tag !== "CreateOrganization") return yield* new Forbidden();
