 17	/** What first sign-in leads to, before any side effect. */
 18	export type SignInDecision =
 19	  | { readonly _tag: "Enter"; readonly candidate: PersonCandidate }
 20	  | { readonly _tag: "ChooseOrganization"; readonly candidates: ReadonlyArray<PersonCandidate> }
 21	  | { readonly _tag: "CreateOrganization" }
 22	  | { readonly _tag: "NotInOrganization" };
