 24	/**
 25	 * The Persons a user may enter as: every Person linked to them, plus, only when the identity
 26	 * provider verified their email, the not-yet-linked Persons with exactly that email (ADR 0002).
 27	 * At most one per Organization, preferring the linked one.
 28	 */
 29	export const candidatesFor = (
 30	  identity: Identity,
 31	  linked: ReadonlyArray<PersonCandidate>,
 32	  unlinkedWithEmail: ReadonlyArray<PersonCandidate>,
 33	): ReadonlyArray<PersonCandidate> => {
 34	  const byOrganization = new Map<OrganizationId, PersonCandidate>();
 35	  for (const candidate of linked) byOrganization.set(candidate.organization.id, candidate);
 36	  if (identity.emailVerified) {
 37	    for (const candidate of unlinkedWithEmail) {
 38	      if (!byOrganization.has(candidate.organization.id)) {
 39	        byOrganization.set(candidate.organization.id, candidate);
 40	      }
 41	    }
 42	  }
 43	  return [...byOrganization.values()].sort((a, b) => a.organization.name.localeCompare(b.organization.name));
 44	};
