 46	/**
 47	 * First sign-in with no Organization in the session: one Person enters, several get a picker, and
 48	 * none leads to "Create an Organization" for an allowlisted verified email, or to "You're not part
 49	 * of an Organization yet" for everyone else.
 50	 */
 51	export const decideSignIn = (
 52	  identity: Identity,
 53	  candidates: ReadonlyArray<PersonCandidate>,
 54	  allowlist: OrganizationCreationAllowlist,
 55	): SignInDecision => {
 56	  const [only, ...rest] = candidates;
 57	  if (only !== undefined && rest.length === 0) return { _tag: "Enter", candidate: only };
 58	  if (only !== undefined) return { _tag: "ChooseOrganization", candidates };
 59	  return allowlist.allows(identity) ? { _tag: "CreateOrganization" } : { _tag: "NotInOrganization" };
 60	};
