102	/** A verified session from the identity provider, and the sealed cookie value that carries it. */
103	export interface ProviderSession {
104	  readonly sealed: Redacted.Redacted<string>;
105	  readonly sessionId: SessionId;
106	  readonly identity: Identity;
107	  /** The WorkOS organization the access token is scoped to, if any. */
