113	/** What the local check of a sealed session found. Network trouble is `AuthUnavailable`, never one of these. */
114	export type SessionCheck =
115	  | { readonly _tag: "Valid"; readonly session: ProviderSession }
116	  /** The access token expired (about 5 minutes): refresh it. */
117	  | { readonly _tag: "Expired" }
118	  /** Missing, tampered, or not a user token: sign in again. */
