123	/**
124	 * WorkOS AuthKit behind a domain interface. The adapter is `@workos-inc/node`'s workerd build;
125	 * tests use a fake. Every call that reaches WorkOS maps transient failures to `AuthUnavailable`.
126	 */
127	export interface IdentityProviderShape {
128	  /** The hosted AuthKit URL (email code, Google, Microsoft). */
129	  readonly authorizationUrl: (options: { readonly redirectUri: string; readonly state: string }) => string;
130	  /** Exchanges the callback's code. Fails `Unauthenticated` for a bad or used code. */
131	  readonly authenticateWithCode: (
132	    code: string,
133	  ) => Effect.Effect<ProviderSession, Unauthenticated | AuthUnavailable>;
134	  /** Verifies the access token locally (JWKS), with no network call once the keys are cached. */
135	  readonly authenticate: (sealed: Redacted.Redacted<string>) => Effect.Effect<SessionCheck, AuthUnavailable>;
136	  /** Rotates the refresh token, optionally switching organization. A terminal failure is `Unauthenticated`. */
137	  readonly refresh: (
138	    sealed: Redacted.Redacted<string>,
139	    organization: Option.Option<WorkosOrganizationId>,
140	  ) => Effect.Effect<ProviderSession, Unauthenticated | AuthUnavailable>;
141	  /** Where to send the browser to end the WorkOS session too. */
142	  readonly logoutUrl: (sessionId: SessionId, returnTo: string) => string;
143	  /** Idempotent per `externalId`: a retry returns the organization the first call created. */
144	  readonly createOrganization: (
145	    name: string,
146	    externalId: OrganizationId,
147	  ) => Effect.Effect<WorkosOrganizationId, AuthUnavailable>;
148	  /** Idempotent: an existing membership is kept as it is (never downgraded). */
149	  readonly ensureMembership: (
150	    userId: WorkosUserId,
151	    organization: WorkosOrganizationId,
152	    role: OrganizationRole,
