276	/**
277	 * The session cookie holds the WorkOS sealed session (access token, refresh token, user), sealed
278	 * with the stage's cookie password. `__Host-` pins it to this exact host over HTTPS, with no
279	 * `Domain` and `Path=/`, so `pr-<n>.submit.surveybeat.app` and other subdomains never see it.
280	 * `SameSite=Lax` keeps it off cross-site POSTs; it is still sent on the top-level GET that
281	 * returns from AuthKit.
282	 */
283	export const SESSION_COOKIE = "__Host-surveybeat-session";
284	/** The OAuth `state` for one sign-in attempt: CSRF protection for `/auth/callback`. */
285	export const STATE_COOKIE = "__Host-surveybeat-auth-state";
286	
287	const SESSION_MAX_AGE = "30 days";
288	const STATE_MAX_AGE = "10 minutes";
289	const cookieOptions = { path: "/", httpOnly: true, secure: true, sameSite: "lax" } as const;
290	
291	/** Everything sign-in needs. The Worker builds these per request; tests provide fakes. */
292	export type AuthServices = IdentityProvider | PeopleIndex | OrganizationPeople | NewIds;
