294	export interface AuthHandlerOptions<R> {
295	  /** Builds the services for one request. */
296	  readonly services: Effect.Effect<Context.Context<AuthServices>, never, R>;
297	  readonly allowlist: Effect.Effect<OrganizationCreationAllowlist, never, R>;
298	}
