300	const randomToken = REDACTED =>
301	  Array.from(crypto.getRandomValues(new Uint8Array(32)), (byte) => byte.toString(16).padStart(2, "0")).join(
302	    "",
303	  );
304	
305	/** This Worker's origin, from the URL Cloudflare received (it is absolute on Workers). */
306	const requestOrigin = Effect.map(HttpServerRequest, (request) =>
307	  URL.canParse(request.originalUrl)
308	    ? new URL(request.originalUrl).origin
309	    : Option.match(toURL(request), { onNone: () => "http://localhost", onSome: (url) => url.origin }),
310	);
311	
312	const sealedFromRequest = Effect.map(HttpServerRequest, (request) =>
313	  Option.map(Option.fromNullishOr(request.cookies[SESSION_COOKIE]), Redacted.make),
314	);
315	
316	const setSessionCookie = (sealed: Redacted.Redacted<string>) =>
317	  HttpEffect.appendPreResponseHandler((_request, response) =>
318	    HttpServerResponse.setCookie(response, SESSION_COOKIE, Redacted.value(sealed), {
319	      ...cookieOptions,
320	      maxAge: SESSION_MAX_AGE,
321	    }).pipe(Effect.orDie),
322	  );
323	
324	const expireSessionCookie = HttpEffect.appendPreResponseHandler((_request, response) =>
325	  HttpServerResponse.expireCookie(response, SESSION_COOKIE, cookieOptions).pipe(Effect.orDie),
326	);
327	
328	/**
329	 * State-changing requests must come from our own pages. `SameSite=Lax` already keeps the cookie
330	 * off cross-site POSTs; this also refuses same-site ones from other subdomains.
331	 */
332	const requireSameOrigin = Effect.gen(function* () {
333	  const request = yield* HttpServerRequest;
334	  const origin = request.headers.origin;
335	  if (origin !== undefined && origin !== (yield* requestOrigin)) return yield* new Forbidden();
336	});
337	
338	/** The per-request check on the cookie. A request it rejects also loses the cookie. */
339	const authenticated = Effect.gen(function* () {
340	  const sealed = yield* sealedFromRequest;
341	  if (Option.isNone(sealed)) return yield* new Unauthenticated();
342	  return yield* checkSession(sealed.value).pipe(
343	    Effect.tapError((error) => (error._tag === "Unauthenticated" ? expireSessionCookie : Effect.void)),
344	    Effect.map((checked) => ({ sealed: sealed.value, checked })),
345	  );
346	});
347	
348	/** Answers the state, writing the session back when a refresh or an Organization switch changed it. */
349	const respond = (sealed: Redacted.Redacted<string>, outcome: SessionOutcome) =>
350	  Effect.gen(function* () {
351	    if (sealedChanged(sealed, outcome.session)) yield* setSessionCookie(outcome.session.sealed);
352	    return outcome.state;
353	  });
