355	/** The `auth` group of `SurveyBeatApi`: AuthKit sign-in, first sign-in, the picker, and sign-out. */
356	export const authHandlers = <R>({ services, allowlist }: AuthHandlerOptions<R>) => {
357	  const provide = <A, E, R>(effect: Effect.Effect<A, E, R>) =>
358	    Effect.flatMap(services, (context) => Effect.provideContext(effect, context));
359	  return HttpApiBuilder.group(SurveyBeatApi, "auth", (handlers) =>
360	    handlers
361	      .handle("login", () =>
362	        provide(
363	          Effect.gen(function* () {
364	            const identityProvider = yield* IdentityProvider;
365	            const state = randomToken();
366	            const url = identityProvider.authorizationUrl({
367	              redirectUri: `${yield* requestOrigin}/auth/callback`,
368	              state,
369	            });
370	            return yield* HttpServerResponse.redirect(url).pipe(
371	              HttpServerResponse.setCookie(STATE_COOKIE, state, { ...cookieOptions, maxAge: STATE_MAX_AGE }),
372	              Effect.orDie,
373	            );
374	          }),
375	        ),
376	      )
377	      .handle("callback", ({ query }) =>
378	        provide(
379	          Effect.gen(function* () {
380	            const request = yield* HttpServerRequest;
381	            const expected = request.cookies[STATE_COOKIE];
382	            const home = `${yield* requestOrigin}/`;
383	            const back = (location: string) =>
384	              HttpServerResponse.redirect(location).pipe(
385	                HttpServerResponse.expireCookie(STATE_COOKIE, cookieOptions),
386	                Effect.orDie,
387	              );
388	            // A missing or different state is a forged or replayed callback: never exchange its code.
389	            if (query.code === undefined || expected === undefined || query.state !== expected) {
390	              return yield* back(`${home}?signin=failed`);
391	            }
392	            const session = yield* (yield* IdentityProvider)
393	              .authenticateWithCode(query.code)
394	              .pipe(Effect.option);
395	            if (Option.isNone(session)) return yield* back(`${home}?signin=failed`);
396	            return yield* back(home).pipe(
397	              Effect.flatMap(
398	                HttpServerResponse.setCookie(SESSION_COOKIE, Redacted.value(session.value.sealed), {
399	                  ...cookieOptions,
400	                  maxAge: SESSION_MAX_AGE,
401	                }),
402	              ),
403	              Effect.orDie,
404	            );
405	          }),
406	        ),
407	      )
408	      .handle("logout", () =>
409	        provide(
410	          Effect.gen(function* () {
411	            yield* requireSameOrigin.pipe(Effect.orDie);
412	            const home = `${yield* requestOrigin}/`;
413	            const sealed = yield* sealedFromRequest;
414	            const logoutUrl = Option.isNone(sealed)
415	              ? Option.none<string>()
416	              : yield* signOut(sealed.value, home).pipe(Effect.orDie);
417	            return yield* HttpServerResponse.redirect(
418	              Option.getOrElse(logoutUrl, () => home),
419	              {
420	                status: 303,
421	              },
422	            ).pipe(HttpServerResponse.expireCookie(SESSION_COOKIE, cookieOptions), Effect.orDie);
423	          }),
424	        ),
425	      )
426	      .handle("session", () =>
427	        provide(
428	          Effect.gen(function* () {
429	            const { sealed, checked } = yield* authenticated;
430	            return yield* sessionState(checked, yield* allowlist).pipe(
431	              Effect.flatMap((outcome) => respond(sealed, outcome)),
432	              // The one Person on offer could not be entered (removed since the index was written).
433	              Effect.catchTag("Forbidden", () => Effect.succeed({ _tag: "NotInOrganization" } as const)),
434	            );
435	          }),
436	        ),
437	      )
438	      .handle("createOrganization", ({ payload }) =>
439	        provide(
440	          Effect.gen(function* () {
441	            yield* requireSameOrigin;
442	            const { sealed, checked } = yield* authenticated;
443	            return yield* respond(sealed, yield* createOrganization(checked, payload.name, yield* allowlist));
444	          }),
445	        ),
446	      )
447	      .handle("chooseOrganization", ({ payload }) =>
448	        provide(
449	          Effect.gen(function* () {
450	            yield* requireSameOrigin;
451	            const { sealed, checked } = yield* authenticated;
452	            return yield* respond(sealed, yield* chooseOrganization(checked, payload.organizationId));
453	          }),
454	        ),
455	      ),
456	  );
457	};

