 57	export class FakeWorkos {
 58	  readonly users = new Map<WorkosUserId, FakeUser>();
 59	  readonly codes = new Map<string, WorkosUserId>();
 60	  readonly sessions = new Map<string, FakeSession>();
 61	  readonly organizations = new Map<OrganizationId, { id: WorkosOrganizationId; name: string }>();
 62	  readonly memberships = new Map<string, OrganizationRole>();
 63	  createOrganizationCalls = 0;
 64	  /** Fail the next N `createOrganization` calls as if WorkOS were down. */
 65	  failCreateOrganization = 0;
 66	  private counter = 0;
 67	
 68	  addUser(email: string, emailVerified = true): string {
 69	    const id = WorkosUserId.make(`user_${++this.counter}`);
 70	    this.users.set(id, { id, email, emailVerified });
 71	    const code = `code_${this.counter}`;
 72	    this.codes.set(code, id);
 73	    return code;
 74	  }
 75	
 76	  private issue(
 77	    userId: WorkosUserId,
 78	    sessionId: SessionId,
 79	    organization: Option.Option<WorkosOrganizationId>,
 80	  ) {
 81	    const sealed = `sealed_${++this.counter}`;
 82	    this.sessions.set(sealed, { sessionId, userId, workosOrganizationId: organization, expired: false });
 83	    return this.toSession(sealed);
 84	  }
 85	
 86	  private toSession(sealed: string): ProviderSession {
 87	    const session = this.sessions.get(sealed);
 88	    const user = session === undefined ? undefined : this.users.get(session.userId);
 89	    if (session === undefined || user === undefined) throw new Error(`no session ${sealed}`);
 90	    return {
 91	      sealed: Redacted.make(sealed),
 92	      sessionId: session.sessionId,
 93	      identity: {
 94	        userId: user.id,
 95	        email: EmailAddress.make(normaliseEmail(user.email)),
 96	        emailVerified: user.emailVerified,
 97	      },
 98	      workosOrganizationId: session.workosOrganizationId,
 99	      role: Option.flatMap(session.workosOrganizationId, (organization) =>
100	        Option.fromNullishOr(this.memberships.get(`${user.id}/${organization}`)),
101	      ),
102	    };
103	  }
104	
105	  /** Lets the access token in this cookie run out, as five minutes would. */
106	  expire(sealed: string) {
107	    const session = this.sessions.get(sealed);
108	    if (session !== undefined) session.expired = true;
109	  }
110	
111	  readonly service = IdentityProvider.of({
112	    authorizationUrl: ({ redirectUri, state }) =>
113	      `https://auth.example.test/authorize?${new URLSearchParams({ redirect_uri: redirectUri, state }).toString()}`,
114	    authenticateWithCode: (code) =>
115	      Effect.suspend(() => {
116	        const userId = this.codes.get(code);
117	        if (userId === undefined) return Effect.fail(new Unauthenticated());
118	        this.codes.delete(code);
119	        return Effect.succeed(this.issue(userId, SessionId.make(`session_${++this.counter}`), Option.none()));
120	      }),
121	    authenticate: (sealed) =>
122	      Effect.sync(() => {
123	        const session = this.sessions.get(Redacted.value(sealed));
124	        if (session === undefined) return { _tag: "Invalid" } as const;
125	        if (session.expired) return { _tag: "Expired" } as const;
126	        return { _tag: "Valid", session: this.toSession(Redacted.value(sealed)) } as const;
127	      }),
128	    refresh: (sealed, organization) =>
129	      Effect.suspend(() => {
130	        const session = this.sessions.get(Redacted.value(sealed));
131	        if (session === undefined) return Effect.fail(new Unauthenticated());
132	        const target = Option.orElse(organization, () => session.workosOrganizationId);
133	        if (Option.isSome(target) && !this.memberships.has(`${session.userId}/${target.value}`)) {
134	          return Effect.fail(new Unauthenticated());
135	        }
136	        // Refresh tokens rotate, but WorkOS replays a just-used one for 30 seconds so concurrent
137	        // refreshes converge. The fake keeps the old cookie usable; `sessions.delete` ends it.
138	        return Effect.succeed(this.issue(session.userId, session.sessionId, target));
139	      }),
140	    logoutUrl: (sessionId, returnTo) =>
141	      `https://auth.example.test/logout?${new URLSearchParams({ session_id: sessionId, return_to: returnTo }).toString()}`,
142	    createOrganization: (name, externalId) =>
143	      Effect.suspend(() => {
144	        this.createOrganizationCalls++;
145	        if (this.failCreateOrganization > 0) {
146	          this.failCreateOrganization--;
147	          return Effect.fail(new AuthUnavailable());
148	        }
149	        const existing = this.organizations.get(externalId);
150	        if (existing !== undefined) return Effect.succeed(existing.id);
151	        const id = WorkosOrganizationId.make(`org_${++this.counter}`);
152	        this.organizations.set(externalId, { id, name });
153	        return Effect.succeed(id);
154	      }),
155	    ensureMembership: (userId, organization, role) =>
156	      Effect.sync(() => {
157	        const key = `${userId}/${organization}`;
158	        if (!this.memberships.has(key)) this.memberships.set(key, role);
159	      }),
160	  });
161	}
