355	  async fetch(path: string, init: RequestInit = {}): Promise<Response> {
356	    const headers = new Headers(init.headers);
357	    if (this.cookies.size > 0) {
358	      headers.set("cookie", [...this.cookies].map(([name, value]) => `${name}=${value}`).join("; "));
359	    }
