361	      new Request(`${ORIGIN}${path}`, { ...init, headers, redirect: "manual" }),
362	    );
363	    for (const header of response.headers.getSetCookie()) {
364	      const [pair = "", ...attributes] = header.split(";").map((part) => part.trim());
365	      const [name = "", value = ""] = pair.split("=");
366	      const expired = attributes.some(
367	        (attribute) => /^max-age=0$/i.test(attribute) || /^expires=.*1970/i.test(attribute),
368	      );
369	      if (expired || value === "") this.cookies.delete(name);
370	      else this.cookies.set(name, value);
371	    }
372	    return response;
373	  }
