237	export class MemoryOrganizations {
238	  readonly organizations = new Map<OrganizationId, { name: string; people: Map<PersonId, FakePerson> }>();
239	
240	  readonly service = OrganizationPeople.of({
241	    createWithAdmin: (organization, admin) =>
242	      Effect.sync(() => {
243	        if (this.organizations.has(organization.id)) return;
244	        this.organizations.set(organization.id, {
245	          name: organization.name,
246	          people: new Map([
247	            [
248	              admin.personId,
249	              { email: normaliseEmail(admin.email), workosUserId: admin.userId, removed: false },
250	            ],
251	          ]),
252	        });
253	      }),
254	    linkPerson: (organizationId, personId, userId, email) =>
255	      Effect.sync(() => {
256	        const people = this.organizations.get(organizationId)?.people;
257	        const person = people?.get(personId);
258	        if (people === undefined || person === undefined || person.removed) return false;
259	        if (person.email !== normaliseEmail(email)) return false;
260	        if ([...people].some(([id, other]) => id !== personId && other.workosUserId === userId)) return false;
261	        if (person.workosUserId === null) person.workosUserId = userId;
262	        return person.workosUserId === userId;
263	      }),
264	    activePerson: (organizationId, userId) =>
265	      Effect.sync(() => {
266	        const people = this.organizations.get(organizationId)?.people ?? new Map<PersonId, FakePerson>();
267	        const found = [...people].find(([, person]) => person.workosUserId === userId && !person.removed);
268	        return Option.map(Option.fromNullishOr(found), ([id]) => id);
269	      }),
270	  });
271	
272	  person(organizationId: OrganizationId, personId: PersonId): FakePerson | undefined {
273	    return this.organizations.get(organizationId)?.people.get(personId);
274	  }
